      alt: "\u5B50\u3069\u3082\u304C\u611F\u60C5\u306E\u6CE2\u306B\u6C17\u3065\u304D\u3001\u547C\u5438\u3084\u8A00\u8449\u3067\u611F\u60C5\u8ABF\u6574\u3057\u3066\u3044\u304F\u69D8\u5B50\u3092\u8868\u3057\u305F\u30A4\u30E9\u30B9\u30C8"
