    english: "Emotional Intelligence",
    short: "\u611F\u60C5\u3092\u77E5\u899A\u3057\u3001\u7406\u89E3\u3057\u3001\u6D3B\u7528\u3057\u3001\u8ABF\u6574\u3059\u308B\u529B\u3002\u5171\u611F\u30FB\u611F\u60C5\u8ABF\u6574\u30FB\u5BFE\u4EBA\u95A2\u4FC2\u3068\u95A2\u308F\u308A\u307E\u3059\u304C\u3001\u80FD\u529B\u30E2\u30C7\u30EB\u3068\u81EA\u5DF1\u8A55\u4FA1\u30E2\u30C7\u30EB\u3092\u533A\u5225\u3057\u3066\u898B\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002",
    updated: "2026-08-11",
